canvas.addEventListener('pointerup',e=>{if(!touchStart)return;const dx=e.clientX-touchStart.x,dy=e.clientY-touchStart.y;if(Math.abs(dx)>25)move(dx<0?-1:1);else if(dy<-20)doJump();else if(dy>20)doDuck();touchStart=null});
function drawBackground(t){const th=theme(),g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#160d26');g.addColorStop(.42,th.dark);g.addColorStop(1,'#130d20');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // soft, drifting bioluminescent motes
 for(let i=0;i<42;i++){let x=(i*173.7+Math.sin(t*.16+i*7)*28)%W,y=(i*97.1+t*(5+i%4)*2)%H;ctx.globalAlpha=.12+((i*13)%7)*.035;ctx.fillStyle=i%3?th.glow:th.b;ctx.beginPath();ctx.arc(x,y,1+(i%3)*.65,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
 const hy=H*.355;const haze=ctx.createRadialGradient(W/2,hy,5,W/2,hy,W*.72);haze.addColorStop(0,th.a+'30');haze.addColorStop(1,'transparent');ctx.fillStyle=haze;ctx.fillRect(0,0,W,H);
}
function drawTunnel(t){const th=theme(),hy=H*.355,near=-.35,far=19;
 // outer organic chamber silhouette
 const lfar=project(-2.3,far),rfar=project(2.3,far),lnear=project(-2.3,near),rnear=project(2.3,near);
 let wall=ctx.createLinearGradient(0,hy,0,H);wall.addColorStop(0,th.dark);wall.addColorStop(.48,th.wall);wall.addColorStop(1,th.floor);ctx.fillStyle=wall;
 ctx.beginPath();ctx.moveTo(lfar.x,lfar.y-H*.5*lfar.s);ctx.lineTo(rfar.x, rfar.y-H*.5*rfar.s);ctx.lineTo(rnear.x,rnear.y-H*.5*rnear.s);ctx.lineTo(rnear.x,rnear.y+H*.5*rnear.s);ctx.lineTo(lnear.x,lnear.y+H*.5*lnear.s);ctx.lineTo(lnear.x,lnear.y-H*.5*lnear.s);ctx.closePath();ctx.fill();
 // floor ribbon
 const a=project(-1.48,far),b=project(1.48,far),c=project(1.48,near),d=project(-1.48,near);ctx.fillStyle=th.floor;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.lineTo(c.x,c.y);ctx.lineTo(d.x,d.y);ctx.closePath();ctx.fill();
 // floor center glow
 const fg=ctx.createLinearGradient(0,hy,0,H);fg.addColorStop(0,th.glow+'10');fg.addColorStop(1,th.glow+'3d');ctx.fillStyle=fg;ctx.beginPath();ctx.moveTo(project(-.72,far).x,project(-.72,far).y);ctx.lineTo(project(.72,far).x,project(.72,far).y);ctx.lineTo(project(.72,near).x,project(.72,near).y);ctx.lineTo(project(-.72,near).x,project(-.72,near).y);ctx.closePath();ctx.fill();
 // luminous lane dividers
 for(const x of [-.5,.5]){const p1=project(x,far),p2=project(x,near);ctx.strokeStyle=th.glow+'42';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke()}
 // transverse floor seams flowing toward the camera
 const interval=2.7,off=world%interval;for(let z=far+interval-off;z>near;z-=interval){if(z>far)continue;const l=project(-1.48,z),r=project(1.48,z),alpha=clamp(1-z/far,.12,.65);ctx.strokeStyle=th.glow+Math.round(alpha*52).toString(16).padStart(2,'0');ctx.lineWidth=Math.max(.6,l.s*1.1);ctx.beginPath();ctx.moveTo(l.x,l.y);ctx.lineTo(r.x,r.y);ctx.stroke()}
 // ribbed tunnel hoops
 const rib=3.35,shift=world%rib;for(let z=far+rib-shift;z>-.5;z-=rib){if(z>far)continue;const p=project(0,z),rx=W*.59*p.s,ry=H*.46*p.s,cy=p.y-H*.39*p.s;ctx.lineWidth=Math.max(.7,p.s*2.8);ctx.strokeStyle=th.glow+'55';ctx.beginPath();ctx.ellipse(W/2,cy,rx,ry,0,0,Math.PI*2);ctx.stroke();ctx.lineWidth=Math.max(.5,p.s*1.2);ctx.strokeStyle='#fff4';ctx.beginPath();ctx.ellipse(W/2,cy,rx*.97,ry*.97,0,0,Math.PI*2);ctx.stroke()}
 // fleshy folds on the walls
 for(let side of [-1,1])for(let i=0;i<4;i++){const z=3+i*3.8+(world*.36%3.8);if(z>19)continue;let p=project(side*(1.9-i*.09),z);ctx.save();ctx.translate(p.x,p.y-H*.31*p.s);ctx.scale(p.s,p.s);ctx.globalAlpha=.18;ctx.strokeStyle=i%2?th.b:th.glow;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-26,0);ctx.bezierCurveTo(-15,-17,14,-17,27,0);ctx.stroke();ctx.globalAlpha=.08;ctx.lineWidth=13;ctx.stroke();ctx.restore()}
 // outer edge rails
 for(const side of [-1,1]){const p1=project(side*1.5,far),p2=project(side*1.5,near);ctx.strokeStyle=th.glow+'72';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.stroke()}
}
function drawStar(x,y,r,rot=0){ctx.save();ctx.translate(x,y);ctx.rotate(rot);ctx.beginPath();for(let i=0;i<10;i++){let a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.45:r;ctx.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}ctx.closePath();ctx.fillStyle='#ffe18c';ctx.shadowColor='#ffe28a';ctx.shadowBlur=r*1.8;ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#fff6d8';ctx.lineWidth=Math.max(1,r*.09);ctx.stroke();ctx.restore()}
function drawObject(o,t){const p=project(o.lane*.88,o.z),s=p.s,ground=p.y,sz=Math.max(3,30*s);if(o.z<-.5)return;ctx.save();ctx.translate(p.x,ground);ctx.globalAlpha=clamp((20-o.z)/3,0,1);
 if(o.type==='star'){let bob=Math.sin(t*4+o.phase)*5*s;drawStar(0,-sz*.9+bob,sz*.55,t*.8);ctx.globalAlpha=.25;ctx.fillStyle='#fff3aa';ctx.beginPath();ctx.ellipse(0,0,sz*.58,sz*.13,0,0,Math.PI*2);ctx.fill()}
 else if(o.type==='bubble'){let bob=Math.sin(t*3+o.phase)*sz*.28;let g=ctx.createRadialGradient(-sz*.22,-sz*.95+bob,1,0,-sz*.72+bob,sz*.68);g.addColorStop(0,'#fff');g.addColorStop(.2,'#d7fff1');g.addColorStop(1,'#59d9c099');ctx.fillStyle=g;ctx.shadowColor='#9effed';ctx.shadowBlur=sz*.6;ctx.beginPath();ctx.arc(0,-sz*.72+bob,sz*.58,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#366b70';ctx.beginPath();ctx.arc(-sz*.18,-sz*.72+bob,sz*.055,0,Math.PI*2);ctx.arc(sz*.16,-sz*.72+bob,sz*.055,0,Math.PI*2);ctx.fill()}
 else if(o.type==='goo'){ctx.fillStyle='#401d48aa';ctx.beginPath();ctx.ellipse(0,-sz*.04,sz*.85,sz*.2,0,0,Math.PI*2);ctx.fill();let g=ctx.createLinearGradient(0,-sz*.7,0,0);g.addColorStop(0,'#ffc1b4');g.addColorStop(.4,'#ff778e');g.addColorStop(1,'#ce4775');ctx.fillStyle=g;ctx.strokeStyle='#ffd2c5';ctx.lineWidth=Math.max(1,s*1.4);ctx.beginPath();ctx.moveTo(-sz*.7,0);ctx.bezierCurveTo(-sz*.9,-sz*.43,-sz*.63,-sz*.64,-sz*.4,-sz*.5);ctx.bezierCurveTo(-sz*.27,-sz*1.06,sz*.22,-sz*.94,sz*.28,-sz*.55);ctx.bezierCurveTo(sz*.74,-sz*.74,sz*.9,-sz*.27,sz*.7,0);ctx.quadraticCurveTo(0,sz*.15,-sz*.7,0);ctx.fill();ctx.stroke();ctx.fillStyle='#682b55';ctx.beginPath();ctx.arc(-sz*.19,-sz*.35,sz*.045,0,7);ctx.arc(sz*.17,-sz*.35,sz*.045,0,7);ctx.fill()}
 else{ctx.fillStyle='#522b49aa';ctx.beginPath();ctx.ellipse(0,0,sz*.75,sz*.19,0,0,7);ctx.fill();let g=ctx.createLinearGradient(-sz*.5,-sz,sz*.45,0);g.addColorStop(0,'#ffe0a2');g.addColorStop(.48,'#ffad80');g.addColorStop(1,'#eb7187');ctx.fillStyle=g;ctx.strokeStyle='#ffe4b9';ctx.lineWidth=Math.max(1,s*1.2);ctx.beginPath();ctx.moveTo(-sz*.55,0);ctx.quadraticCurveTo(-sz*.48,-sz*.85,0,-sz*.78);ctx.quadraticCurveTo(sz*.62,-sz*.72,sz*.55,0);ctx.quadraticCurveTo(0,sz*.16,-sz*.55,0);ctx.fill();ctx.stroke();ctx.fillStyle='#754258';ctx.beginPath();ctx.arc(-sz*.14,-sz*.36,sz*.045,0,7);ctx.arc(sz*.16,-sz*.36,sz*.045,0,7);ctx.fill()}
 ctx.restore()}

