function drawRunner(t){const p=project(lane*.88,0),s=p.s,air=jump>0?Math.sin((.78-jump)/.78*Math.PI):0,squash=duck>0?.66:1,x=p.x,y=p.y-air*H*.15;const r=clamp(s,0.65,1.55);ctx.save();ctx.translate(x,y);ctx.scale(r,r);
 // soft ground shadow
 ctx.globalAlpha=.25*(1-air*.7);ctx.fillStyle='#160d24';ctx.beginPath();ctx.ellipse(0,0,24*(1-air*.35),7*(1-air*.4),0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
 // little legs and shoes
 if(duck<=0){let run=Math.sin(t*17)*5*(1-air),legY=2;ctx.strokeStyle='#5e385f';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-8,legY-9);ctx.lineTo(-10+run,legY+1);ctx.moveTo(8,legY-9);ctx.lineTo(10-run,legY+1);ctx.stroke();ctx.fillStyle='#ffe09a';ctx.beginPath();ctx.ellipse(-11+run,legY+1,7,3,0,0,7);ctx.ellipse(11-run,legY+1,7,3,0,0,7);ctx.fill()}
 // arms
 ctx.strokeStyle='#ffd2bc';ctx.lineWidth=6;ctx.lineCap='round';let arm=Math.sin(t*17)*3*(1-air);ctx.beginPath();ctx.moveTo(-15,-27);ctx.lineTo(-22,-17+arm);ctx.moveTo(15,-27);ctx.lineTo(22,-18-arm);ctx.stroke();
 // body capsule, ducking gives a delightful squish
 ctx.save();ctx.translate(0,-26);ctx.scale(1,squash);let body=ctx.createLinearGradient(-18,-31,17,5);body.addColorStop(0,'#fff0d6');body.addColorStop(.52,'#ffc4ac');body.addColorStop(1,'#ff879e');ctx.fillStyle=body;ctx.strokeStyle='#fff0d9';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,-14,18,24,0,0,Math.PI*2);ctx.fill();ctx.stroke();
 // tiny belly patch
 ctx.fillStyle='#ffddc6';ctx.globalAlpha=.85;ctx.beginPath();ctx.ellipse(0,-3,8,7,0,0,7);ctx.fill();ctx.globalAlpha=1;
 // eyes / cheeks / grin
 ctx.fillStyle='#412847';ctx.beginPath();ctx.ellipse(-6,-19,2.1,3.1,-.15,0,7);ctx.ellipse(6,-19,2.1,3.1,.15,0,7);ctx.fill();ctx.fillStyle='#fa8998';ctx.beginPath();ctx.arc(-11,-13,2.4,0,7);ctx.arc(11,-13,2.4,0,7);ctx.fill();ctx.strokeStyle='#874459';ctx.lineWidth=1.6;ctx.beginPath();ctx.arc(0,-14,4.5,.15,Math.PI-.15);ctx.stroke();
 // headband
 ctx.fillStyle='#7edfc5';ctx.beginPath();ctx.roundRect(-16,-35,32,5,3);ctx.fill();ctx.fillStyle='#fff1a7';ctx.beginPath();ctx.arc(0,-36,3.4,0,7);ctx.fill();ctx.restore();
 // sparkly little trail
 if(mode==='playing'){ctx.globalAlpha=.45;drawStar(-25-Math.sin(t*5)*3,-35,3+Math.sin(t*4)*.7,t);ctx.globalAlpha=1}ctx.restore()}
function drawEffects(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=220*dt;p.life-=dt;if(p.life<=0){particles.splice(i,1);continue}ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,7);ctx.fill()}ctx.globalAlpha=1}
function render(dt){const t=time;drawBackground(t);drawTunnel(t);const sorted=objects.slice().sort((a,b)=>b.z-a.z);for(const o of sorted)drawObject(o,t);drawRunner(t);drawEffects(dt);
 if(hitFlash>0){ctx.fillStyle=`rgba(255,111,138,${Math.sin(t*28)*.10+.08})`;ctx.fillRect(0,0,W,H)}
 // quiet scene title detail
 if(mode==='playing'){ctx.save();ctx.globalAlpha=.7;ctx.fillStyle='#fff';ctx.font='700 9px DM Mono,monospace';ctx.textAlign='center';ctx.fillText('KEEP MOVING',W/2,H*.355-18);ctx.restore()}
}
